                            id: string;
                            /** @description Run-invariant verdict cut from the run-aggregate report; null without report. */
                            invariant_summary: components["schemas"]["InvariantSummary"] | null;
                            ko_count: number | null;
                            /** @enum {string} */
                            load_window_state: "measured" | "pending" | "unavailable";
                            ok_count: number | null;
                            /** @description Result counts KOs or console errors. */
                            result_has_errors: boolean;
                            /** @description Load container exit code; 2 = SLA assertions violated; null = no exit observed. */
                            run_exit_code: number | null;
                            /** @description Snapshot written before load started; null unless run_manifest_state is captured. */
                            run_manifest: components["schemas"]["RunManifestView"] | null;
                            /** @enum {string} */
                            run_manifest_state: "captured" | "pending" | "unavailable";
                            saved_run_id: string | null;
                            saved_run_name: string | null;
                            scenario_id: string | null;
                            /** @description LoadCraft SLA verdict from simulation.log; null if the load container did not finish. */
                            sla_verdict: components["schemas"]["SlaVerdict"] | null;
                            /**
                             * @description Null = legacy/unlabelled.
                             * @enum {string|null}
                             */
                            source: "manual" | "saved_run" | "scheduled" | "self_check" | null;
                            /** Format: date-time */
                            started_at: string | null;
                            /** @enum {string} */
                            status: "pending" | "building" | "running" | "completed" | "failed" | "cancelled";
                            /** @description This server process drives the run; meaningless on terminal rows. building/running with false = abandoned. */
